package com.nook.service;
import com.nook.application.port.out.PushNotificationPort; import com.nook.domain.SocialEntities.*; import com.nook.dto.ApiDtos.*; import com.nook.exception.ApiException; import com.nook.mapper.SocialMapper; import com.nook.repository.SocialRepository; import jakarta.persistence.EntityManager; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*;
@Service public class DiscoveryService { final SocialRepository repo;final SocialMapper mapper;final EntityManager em;final PushNotificationPort push;final AuditService audit;public DiscoveryService(SocialRepository r,SocialMapper m,EntityManager e,PushNotificationPort push,AuditService audit){repo=r;mapper=m;em=e;this.push=push;this.audit=audit;} public PageDto<DiscoverProfile> discover(UUID me,int page,int size){Preference f=repo.preference(me);Profile viewer=repo.profile(me);Set<String> genders=new HashSet<>(mapper.split(f.desiredGenders)),intentions=new HashSet<>(mapper.split(f.intentions)),vibes=new HashSet<>(mapper.split(f.preferredVibes)),moments=new HashSet<>(mapper.split(f.preferredMoments)),styles=new HashSet<>(mapper.split(f.meetingStyles));List<DiscoverProfile> all=repo.discover(me,f.minAge,f.maxAge).stream().filter(p->mapper.distance(viewer.latitude,viewer.longitude,p.latitude,p.longitude)<=f.maxDistanceKm).filter(p->genders.isEmpty()||genders.contains(p.gender.name())).filter(p->intentions.isEmpty()||intentions.contains(p.lookingFor.name())).filter(p->vibes.isEmpty()||p.preferredVibe!=null&&vibes.contains(p.preferredVibe)).filter(p->moments.isEmpty()||p.favoriteCoffeeMoment!=null&&moments.contains(p.favoriteCoffeeMoment)).filter(p->styles.isEmpty()||p.preferredPlan!=null&&styles.contains(p.preferredPlan)).map(p->mapper.profile(me,p)).toList();int from=Math.min(page*size,all.size()),to=Math.min(from+size,all.size());return new PageDto<>(all.subList(from,to),page,size,to<all.size());}
 @Transactional public LikeResult like(UUID me,UUID other){if(me.equals(other))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_LIKE","No puedes enviar este café");repo.lockUsers(me,other);User target=repo.user(other);if(target==null||!target.active||repo.blocked(me,other))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_LIKE","No puedes enviar este café");em.createNativeQuery("insert into coffee_likes(id,sender_id,receiver_id,created_at) values(gen_random_uuid(),:a,:b,now()) on conflict(sender_id,receiver_id) do nothing").setParameter("a",me).setParameter("b",other).executeUpdate();audit.record(me,"LIKE","USER",other);if(!repo.likeExists(other,me))return new LikeResult(false,null);UUID one=me.toString().compareTo(other.toString())<0?me:other,two=one.equals(me)?other:me;int created=em.createNativeQuery("insert into matches(id,user_one_id,user_two_id,active,created_at,updated_at) values(gen_random_uuid(),:a,:b,true,now(),now()) on conflict(user_one_id,user_two_id) do nothing").setParameter("a",one).setParameter("b",two).executeUpdate();Match m=repo.match(me,other).orElseThrow();em.createNativeQuery("insert into conversations(id,match_id,created_at,updated_at) values(gen_random_uuid(),:m,now(),now()) on conflict(match_id) do nothing").setParameter("m",m.id).executeUpdate();Conversation c=repo.conversationByMatch(m.id);em.createNativeQuery("insert into conversation_participants(conversation_id,user_id) values(:c,:a),(:c,:b) on conflict do nothing").setParameter("c",c.id).setParameter("a",one).setParameter("b",two).executeUpdate();if(created>0){push.deliver(other,"MATCH","¡Tenemos café!",repo.profile(me).name+" también se tomaría un café contigo",m.id);audit.record(me,"MATCH_CREATED","MATCH",m.id);}return new LikeResult(true,toDto(me,m,c.id));}
 @Transactional public void pass(UUID me,UUID other){if(me.equals(other)||repo.user(other)==null)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_PASS","No puedes descartar este perfil");if(!repo.passExists(me,other)){UserPass pass=new UserPass();pass.senderId=me;pass.receiverId=other;repo.save(pass);audit.record(me,"PASS","USER",other);}}
 public List<MatchDto> matches(UUID me){return repo.matches(me).stream().map(m->toDto(me,m,repo.conversationByMatch(m.id).id)).toList();} MatchDto toDto(UUID me,Match m,UUID c){UUID other=m.userOneId.equals(me)?m.userTwoId:m.userOneId;return new MatchDto(m.id,mapper.profile(me,repo.profile(other)),m.createdAt,c);}
 @Transactional public void deleteMatch(UUID me,UUID id){Match m=repo.find(Match.class,id);if(m==null||(!m.userOneId.equals(me)&&!m.userTwoId.equals(me)))throw new ApiException(HttpStatus.NOT_FOUND,"MATCH_NOT_FOUND","Match no encontrado");m.active=false;}
}
